def longestCommonPrefix(self, strs: list[str]) -> str:
    if not strs:
        return ""
    min_len = min(len(s) for s in strs)
    lo, hi = 0, min_len
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if all(s[:mid] == strs[0][:mid] for s in strs):
            lo = mid
        else:
            hi = mid - 1
    return strs[0][:lo]

